import{_ as t,o as a,c as i,a9 as r}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture-roadmap.md","filePath":"architecture-roadmap.md","lastUpdated":null}'),n={name:"architecture-roadmap.md"};function o(s,e,l,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h1><p>PerfChecker separates the controller, the measured programs and presentation. The same test definitions work from VS Code, a script or a web controller; results cross those boundaries as versioned data with measurement definitions and provenance attached.</p><h2 id="Packages-and-ownership" tabindex="-1">Packages and ownership <a class="header-anchor" href="#Packages-and-ownership" aria-label="Permalink to &quot;Packages and ownership {#Packages-and-ownership}&quot;">​</a></h2><ul><li><p><code>PerfChecker</code> — discovery, plans, workers, measurements, comparisons, CLI, REPL, reports. No required web, notebook or plotting framework.</p></li><li><p><code>PerfCheckerWeb</code> — Oxygen routes, studio assets, auth, jobs. Depends on the web stack.</p></li><li><p><code>PerfCheckerPluto</code> — notebook generation, controls, Pluto launch. Depends on Pluto and PlutoUI.</p></li><li><p><code>PerfCheckerMakie</code> — figures and dashboards. Depends on Makie; WGLMakie is an optional renderer.</p></li><li><p><strong>VS Code client</strong> — testing view, commands, source navigation. Separate TypeScript project that calls the Julia controller.</p></li><li><p><code>PerfCheckerQualification</code> — impact planning, contracts, matrix receipts. Independent stdlib-only package.</p></li><li><p><code>website/</code> — this documentation. Its own Documenter/Vitepress environment.</p></li></ul><p>The Julia satellites live in <code>packages/</code> in the same repository, so a shared-contract change and its consumers can be reviewed together. Each satellite has its own project, compat bounds and tests. Installation requires the explicit satellite package; loading Oxygen or Makie alone no longer activates an interface.</p><p>PerfChecker does not need a global active backend. A notebook, a web job and a VS Code item have their own controller state and may stay open together.</p><h2 id="Extensions-that-stay-useful" tabindex="-1">Extensions that stay useful <a class="header-anchor" href="#Extensions-that-stay-useful" aria-label="Permalink to &quot;Extensions that stay useful {#Extensions-that-stay-useful}&quot;">​</a></h2><p>Small interoperability methods stay in Julia extensions: BenchmarkTools and Chairmarks measurements, the TestItemRunner bridge, UnicodePlots rendering and Documenter report blocks. They adapt an existing API without owning an application or a large dependency tree.</p><ul><li><p>An interface with assets, server lifecycle or notebook generation belongs in a satellite.</p></li><li><p>A diagnostic tool that must inspect the target environment belongs in a worker adapter.</p></li><li><p>Adding a new dependency should begin with this ownership choice, not another entry in the engine&#39;s weak-dependency list.</p></li></ul><h2 id="Diagnostic-workers" tabindex="-1">Diagnostic workers <a class="header-anchor" href="#Diagnostic-workers" aria-label="Permalink to &quot;Diagnostic workers {#Diagnostic-workers}&quot;">​</a></h2><p>JET, AllocCheck, SnoopCompile and Aqua adapters live under <code>providers/</code>, each declaring its tool compatibility separately.</p><ul><li><p>The worker loads the requested tool in its prepared environment.</p></li><li><p>It does not import PerfChecker.</p></li><li><p>An unavailable tool returns explicit diagnostic evidence. It does not fail the controller import.</p></li><li><p>Provider source participates in development-source fingerprints, so editing an adapter changes the recorded source identity.</p></li></ul><h2 id="One-collection,-several-environments" tabindex="-1">One collection, several environments <a class="header-anchor" href="#One-collection,-several-environments" aria-label="Permalink to &quot;One collection, several environments {#One-collection,-several-environments}&quot;">​</a></h2><p>A collection is a set of compatible, tested component versions — not one Manifest containing every optional interface. An Oxygen controller using HTTP 2 and a Pluto controller using HTTP 1 can exchange saved bundles while keeping separate environments.</p><ul><li><p>The qualification runner resolves and saves each lane&#39;s actual environment.</p></li><li><p>Core and shared-contract changes select all consumers; a web-only change selects web tests and its dependent documentation.</p></li><li><p>The full matrix also checks historical multi-interface integration in a separate environment.</p></li></ul><p>The <a href="./reference/qualification">qualification contract</a> requires the same candidate revisions, campaign ID, successful lanes and unmodified artifacts before publication. A targeted PR result cannot promote a complete collection.</p><p>&lt;a id=&quot;Register-packages-from-the-shared-repository&quot;&gt;&lt;/a&gt;</p><h2 id="Registering-from-the-shared-repository" tabindex="-1">Registering from the shared repository <a class="header-anchor" href="#Registering-from-the-shared-repository" aria-label="Permalink to &quot;Registering from the shared repository {#Registering-from-the-shared-repository}&quot;">​</a></h2><p>General supports a package in a repository subdirectory. Its registry entry records the repository and the package&#39;s <code>subdir</code>; users still install it by name.</p><ul><li><p><code>packages/PerfCheckerWeb</code> is a package source root with its own <code>Project.toml</code> and <code>src/</code>.</p></li><li><p>It is not a nested module loaded through the parent&#39;s directory.</p></li><li><p>Its dependency on PerfChecker is declared by UUID and resolved by Pkg.</p></li></ul><p>The local <code>[sources.PerfChecker]</code> path is a development convenience when an interface project is active; Pkg does not propagate it when the interface is installed as a dependency.</p><p>Registration is separate per package, for example <code>@JuliaRegistrator register subdir=packages/PerfCheckerWeb</code> on a published release commit. The engine version required by an interface&#39;s compat bounds must also be registered.</p><h2 id="Test-items-and-performance-evidence" tabindex="-1">Test items and performance evidence <a class="header-anchor" href="#Test-items-and-performance-evidence" aria-label="Permalink to &quot;Test items and performance evidence {#Test-items-and-performance-evidence}&quot;">​</a></h2><ul><li><p>The TestItemRunner bridge discovers existing declarations and can run one item in a fresh process.</p></li><li><p>Untagged items are shared. <code>:perf_only</code> and <code>:test_only</code> separate the two modes.</p></li><li><p>Functional success, a completed measurement and a passing regression budget are three separate results.</p></li><li><p>Ordinary test-item timing includes setup and assertions; feature workloads give a narrower measurement region.</p></li></ul><p>Saved bundles retain the metric definition, runtime, source identity, environment and qualification outcome needed to judge comparability.</p><h2 id="Platform-limits" tabindex="-1">Platform limits <a class="header-anchor" href="#Platform-limits" aria-label="Permalink to &quot;Platform limits {#Platform-limits}&quot;">​</a></h2><ul><li><p>Windows and Linux are recorded separately.</p></li><li><p>macOS is not currently qualified.</p></li><li><p>The cross-machine estimator is an experimental planning aid; predictions never replace measurements or qualify a blocking CI decision.</p></li></ul><p><a id="Extensions-that-remain-useful"></a><a id="Platform-and-prediction-limits"></a><a id="Temporary-previews-before-registration"></a></p>',28)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
